def _strip_grouping(string):
    """Strip grouping characters (commas and underscores) from a numeric string."""
    return string.replace(',', '').replace('_', '')


def convert_with_grouping(converter):
    """Wrap a converter to strip grouping characters before conversion."""
    def wrapper(string, match):
        return converter(_strip_grouping(string))
    return wrapper

